package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import java.time.*;

/** User-selected silent pre-travel bedtime reminders; no alarm, playback or light output. */
final class TripSleepRuntime {
    static final String ACTION="org.sleepwell.app.TRIP_SLEEP_REMINDER",CHANNEL="travel_sleep_adjustment_v1";
    static final int ID=746;
    private static PendingIntent pending(Context c,String token,int flags){return PendingIntent.getBroadcast(c,ID,new Intent(c,TripSleepReceiver.class).setAction(ACTION).setIdentifier(token),flags|PendingIntent.FLAG_IMMUTABLE);}
    private static void cancel(Context c,String token){if(token.isEmpty())return;PendingIntent old=pending(c,token,PendingIntent.FLAG_NO_CREATE);if(old!=null){c.getSystemService(AlarmManager.class).cancel(old);old.cancel();}}
    static void channel(Context c){NotificationChannel ch=new NotificationChannel(CHANNEL,"Travel sleep schedule",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Silent bedtime reminders for dates you reviewed before travel.");ch.setSound(null,null);ch.enableVibration(false);c.getSystemService(NotificationManager.class).createNotificationChannel(ch);}
    static boolean allowed(Context c){if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return false;NotificationManager m=c.getSystemService(NotificationManager.class);NotificationChannel ch=m.getNotificationChannel(CHANNEL);return m.areNotificationsEnabled()&&(ch==null||ch.getImportance()!=NotificationManager.IMPORTANCE_NONE);}
    static void save(Context c,TripSleepPlan draft){synchronized(TripSleepStore.LOCK){TravelPlan trip=TravelPlans.repository(c).load(System.currentTimeMillis());if(draft.reminders&&draft.next(System.currentTimeMillis(),0)==null)throw new IllegalStateException("All selected reminders have passed. Review a later trip or save with reminders off.");new TripSleepStore(c).save(draft,trip);reconcile(c,true);}}
    static void reconcile(Context c){reconcile(c,true);}
    private static void reconcile(Context c,boolean dismiss){synchronized(TripSleepStore.LOCK){TripSleepStore store=new TripSleepStore(c);String old=store.pending();store.pending("");cancel(c,old);if(dismiss)c.getSystemService(NotificationManager.class).cancel(ID);try{TripSleepPlan p=store.load();if(p==null)return;TravelPlan trip=TravelPlans.repository(c).load(System.currentTimeMillis());if(!p.matches(trip)){store.status("Trip changed. Review and save the sleep schedule again.");return;}if(!p.reminders){store.error("");return;}TripSleepPlan.Night night=p.next(System.currentTimeMillis(),store.delivered());if(night==null){store.status("The selected reminder dates have ended.");store.error("");return;}channel(c);String token="trip-sleep:"+p.revision+":"+night.index+":"+night.remind;store.pending(token);c.getSystemService(AlarmManager.class).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,night.remind,pending(c,token,PendingIntent.FLAG_UPDATE_CURRENT));store.status("Next reminder: "+RecordUi.date(night.remind,ZoneId.of(p.home))+" "+RecordUi.clock(c,night.remind,ZoneId.of(p.home)));store.error("");}catch(RuntimeException error){store.error("Schedule saved; reminder needs attention. Retry from Travel sleep schedule.");throw error;}}}
    static void receive(Context c,String incoming){synchronized(TripSleepStore.LOCK){TripSleepStore store=new TripSleepStore(c);if(incoming==null||!incoming.equals(store.pending()))return;TripSleepPlan p=store.load();TravelPlan trip=TravelPlans.repository(c).load(System.currentTimeMillis());if(p==null||!p.reminders||!p.matches(trip)){reconcile(c);return;}TripSleepPlan.Night due=null;for(TripSleepPlan.Night night:p.nights())if(incoming.equals("trip-sleep:"+p.revision+":"+night.index+":"+night.remind)){due=night;break;}if(due==null||due.remind<=store.delivered())return;long now=System.currentTimeMillis();if(now<due.remind)return;boolean late=now-due.remind>15*60000L;store.consume(due.remind,late?"A delayed travel sleep reminder was skipped.":"Travel sleep reminder processed.");try{if(!late&&allowed(c)){channel(c);PendingIntent open=PendingIntent.getActivity(c,ID,new Intent(c,TripSleepActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String text="Bed "+RecordUi.clock(c,due.bed,ZoneId.of(p.home))+" · wake "+RecordUi.clock(c,due.wake,ZoneId.of(p.home))+" · "+TravelPlan.city(p.home);Notification n=new androidx.core.app.NotificationCompat.Builder(c,CHANNEL).setSmallIcon(Icons.resource("moon")).setContentTitle("Your pre-travel sleep schedule").setContentText(text).setContentIntent(open).setSilent(true).setOnlyAlertOnce(true).setAutoCancel(true).build();c.getSystemService(NotificationManager.class).notify(ID,n);store.status("Your travel sleep reminder was shown.");}else if(!late)store.status("A travel sleep reminder was skipped because notifications were blocked.");}catch(RuntimeException failure){store.error("The last travel sleep reminder could not be shown.");}finally{reconcile(c,false);}}}
    static void recoverExisting(Context c){Context app=c.getApplicationContext();new Thread(()->{try{if(new TripSleepStore(app).prefs.contains("plan"))reconcile(app);}catch(RuntimeException failure){try{new TripSleepStore(app).error("Travel sleep reminders need attention after restart.");}catch(RuntimeException ignored){android.util.Log.e("SleepWell","Travel sleep recovery unavailable",failure);}}},"SleepWell-travel-sleep-recover").start();}
    private TripSleepRuntime(){}
}
